insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('b787376c-1fe5-4529-99e5-37881f23ecea', 'a8b72ca0-cf91-411a-8a67-464c939c669c', $$inleiding: hogere rijstprijs; India stelt exportverbod in voor voedselzekerheid$$,
   $$economie-vwo-2026-ii-indiase-rijst-context1.png$$,
   $$Klimaatverandering zorgt voor een daling van de productie van rijst per hectare, waardoor de prijs van rijst is gestegen. Rijst geldt als de belangrijkste bron van voedsel in India. De Indiase overheid wil voedselzekerheid voor haar burgers en stelt daarom een exportverbod in voor rijst. Voedselzekerheid wordt bepaald door te kijken naar de hoeveelheid rijst die mensen kunnen kopen.$$, 'inline'),
  ('708c43f7-35e6-4ba5-80e1-0cfd9e16426b', 'a8b72ca0-cf91-411a-8a67-464c939c669c', $$econoom onderzoekt voedselzekerheid in India$$,
   $$economie-vwo-2026-ii-indiase-rijst-context2.png$$,
   $$Een econoom onderzoekt de voedselzekerheid in India (zie tabel 1).$$, 'inline'),
  ('34925b0c-105b-4f9e-aabd-a4f71e0dbe65', 'a8b72ca0-cf91-411a-8a67-464c939c669c', $$tabel 1: gegevens van India 2019–2022$$,
   $$economie-vwo-2026-ii-indiase-rijst-context3.png$$,
   $$Tabel 1 Gegevens van India
| 2019 | 2020 | 2021 | 2022
prijsindex van rijst (basisjaar 2019) | 100 | 103,1 | 132,2 | 151,0
wegingsfactor rijst als aandeel van het totale uitgavenpakket | 20% | 20% | 20% | 20%
nominaal bbp per hoofd van de bevolking (in US$) | $ 2.050 | $ 1.913 | $ 2.238 | $ 2.288$$, 'inline'),
  ('92bf1984-326e-4caf-9145-1d55b2bf1823', 'a8b72ca0-cf91-411a-8a67-464c939c669c', $$overige prijzen stegen in 2019–2022 met 15%$$,
   $$economie-vwo-2026-ii-indiase-rijst-context4.png$$,
   $$In de periode 2019–2022 stegen de overige prijzen in India met 15%.$$, 'inline'),
  ('eecce18c-d1a7-4f94-b825-b539fc380515', 'a8b72ca0-cf91-411a-8a67-464c939c669c', $$overheidsprogramma: garantieprijs $ 750 en verkoop aan laagste inkomens voor $ 125 per ton$$,
   $$economie-vwo-2026-ii-indiase-rijst-context5.png$$,
   $$De Indiase overheid start vanaf 2023 een programma om mensen met de laagste inkomens verder te helpen. Dit houdt in:
− De overheid koopt rijst op tegen een garantieprijs van $ 750 per ton.
− De overheid verkoopt de rijst in speciale winkels aan mensen met de laagste inkomens voor $ 125 per ton. De lokale overheid registreert deze mensen en zij moeten een identiteitsbewijs tonen.$$, 'inline'),
  ('89506f71-30b6-4c30-829e-2ce98bb3f469', 'a8b72ca0-cf91-411a-8a67-464c939c669c', $$econoom analyseert het programma met een vraag- en aanbodmodel$$,
   $$economie-vwo-2026-ii-indiase-rijst-context6.png$$,
   $$Een econoom analyseert de gevolgen van het programma met een vraag- en aanbodmodel (zie figuur 1).$$, 'inline'),
  ('f660a404-c4ed-4492-ba5f-8ac230dd6c97', 'a8b72ca0-cf91-411a-8a67-464c939c669c', $$figuur 1: vraag- en aanbodmodel van rijst, met vergelijkingen$$,
   $$economie-vwo-2026-ii-indiase-rijst-context7.png$$,
   $$Figuur 1 Vraag- en aanbodmodel van rijst
verticale as: P (in $), 0 tot 1250; horizontale as: Q (in miljoenen tonnen), 0 tot 600.
Dalende vraaglijn V en stijgende aanbodlijn A.
Hierbij geldt dat:
De vraag (V): Qv = –0,4P + 550
Het aanbod (A): Qa = 0,8P – 100
Q is in miljoenen tonnen
P is de prijs per ton (in $)$$, 'inline'),
  ('bd585560-e390-4d39-bc49-c34accc32d57', 'a8b72ca0-cf91-411a-8a67-464c939c669c', $$programma leidt per saldo tot verlies voor de overheid$$,
   $$economie-vwo-2026-ii-indiase-rijst-context8.png$$,
   $$Het programma leidt per saldo tot een verlies voor de overheid.$$, 'inline'),
  ('b12b4f40-66d5-484f-8732-82d8931980e4', 'a8b72ca0-cf91-411a-8a67-464c939c669c', $$producenten gaan er door het programma op vooruit$$,
   $$economie-vwo-2026-ii-indiase-rijst-context9.png$$,
   $$Producenten gaan er door het programma op vooruit.$$, 'inline'),
  ('a8c95699-196c-43e6-9f63-30a031f812c0', 'a8b72ca0-cf91-411a-8a67-464c939c669c', $$uitwerkbijlage vraag 4: figuur 1$$,
   $$economie-vwo-2026-ii-indiase-rijst-context10.png$$,
   $$uitwerkbijlage vraag 4
Figuur 1 Vraag en aanbodmodel van rijst (kopie van figuur 1 met V en A)$$, 'uitwerkbijlage'),
  ('e452b552-67b1-4f33-bf65-4baea622f515', '11f0f7e4-a9c4-4ce1-9f93-aac3242446a8', $$inleiding: kredietverleners laten wanbetalingsrisico onderzoeken door het BLA$$,
   $$economie-vwo-2026-ii-krediet-onderzocht-context1.png$$,
   $$Kredietverleners (bijvoorbeeld banken) willen weten wat het risico is op wanbetaling door potentiële kredietnemers (geldleners). Dit kunnen kredietverleners zelf onderzoeken, maar ook laten doen door het Bureau Leen Administratie (BLA). Het BLA voert dit kredietonderzoek uit voor aangesloten kredietverleners.$$, 'inline'),
  ('baca1d22-4b6e-48c1-937b-b9bf7fad69ea', '11f0f7e4-a9c4-4ce1-9f93-aac3242446a8', $$BLA-tarief als vast percentage van het krediet; alleen kredieten boven € 50.000$$,
   $$economie-vwo-2026-ii-krediet-onderzocht-context2.png$$,
   $$Kredietverleners betalen per onderzoek een vast percentage van het krediet. Het BLA voert alleen onderzoek uit bij een krediet groter dan € 50.000. Het BLA heeft alleen gegevens van de bij het BLA aangesloten kredietverleners. Ieder kredietonderzoek heeft dezelfde kostprijs.$$, 'inline'),
  ('d9bee121-b84b-47b7-b29d-f49f6a941537', '11f0f7e4-a9c4-4ce1-9f93-aac3242446a8', $$bij wanbetaling draagt de gemeente de bemiddelingskosten$$,
   $$economie-vwo-2026-ii-krediet-onderzocht-context3.png$$,
   $$In het geval van wanbetaling draagt de gemeente de kosten van bemiddeling tussen kredietverleners en kredietnemers. Door het BLA daalt het risico van wanbetaling.$$, 'inline'),
  ('e79b199f-b715-4a1e-ad29-91c6613aad99', '11f0f7e4-a9c4-4ce1-9f93-aac3242446a8', $$premiedifferentiatie naar wanbetalingsrisico$$,
   $$economie-vwo-2026-ii-krediet-onderzocht-context4.png$$,
   $$Kredietverleners vragen lagere premies voor kredietnemers die een lager risico op wanbetaling hebben. Dit wordt premiedifferentiatie genoemd.$$, 'inline'),
  ('aac8c5ae-2c73-4fbe-9cc0-6d0057411920', '11f0f7e4-a9c4-4ce1-9f93-aac3242446a8', $$hypotheekbank SVD overweegt inzet BLA$$,
   $$economie-vwo-2026-ii-krediet-onderzocht-context5.png$$,
   $$Hypotheekbank SVD overweegt de inzet van het BLA. De directeur maakt hiervoor een analyse (zie tabel 2).$$, 'inline'),
  ('010f251f-7a0c-469a-86f6-27d3e2848057', '11f0f7e4-a9c4-4ce1-9f93-aac3242446a8', $$tabel 2: kredietgegevens SVD – voorspelling 2025–2035, met noten$$,
   $$economie-vwo-2026-ii-krediet-onderzocht-context6.png$$,
   $$Tabel 2 Kredietgegevens SVD – voorspelling 2025–2035
| zonder inzet BLA | met inzet BLA
totale omzet | |
aantal afgesloten kredieten | 50.000 | 48.000
gemiddelde omvang krediet | € 310.000 | € 340.000
gemiddeld rentepercentage | 4,1% | 3,9%
totale kosten | € 568,695 miljoen | …
schadekosten¹⁾ | 9% | 3%
vermogenskosten²⁾ | 3,3% | 3,3%
jaarlijks tarief BLA (als % van het verleende krediet) | - | 0,05%
noot 1 de schadekosten van wanbetaling als percentage van de omzet
noot 2 kosten voor het aantrekken van het benodigde vermogen als percentage van het verleende krediet$$, 'inline'),
  ('831fea83-69c6-4353-a2c8-1e372180449c', '11f0f7e4-a9c4-4ce1-9f93-aac3242446a8', $$SVD leent kort op de geldmarkt en leent lang uit met rentevaste periode$$,
   $$economie-vwo-2026-ii-krediet-onderzocht-context7.png$$,
   $$De SVD leent zelf op de geldmarkt. Hier sluit de SVD kortlopende leningen af om dit vervolgens uit te lenen via kredieten met een vaste looptijd van 30 jaar en een rentevaste periode. Dit is een periode waarin de rente op een krediet gelijk blijft. Als de centrale bank monetair beleid voert zal de rente op de geldmarkt veranderen.$$, 'inline'),
  ('9243804a-efb9-4d1b-a797-6d2a9b3ab0d5', 'c1892a3e-eb61-4ff8-bc5b-58420322f41e', $$inleiding: hoge inflatie; hogere refirente leidt niet tot hogere spaarquote$$,
   $$economie-vwo-2026-ii-flexibele-inflatie-context1.png$$,
   $$Een land heeft al langere tijd te maken met een hoge inflatie. De centrale bank van het land heeft de refirente een aantal keer verhoogd. Dit heeft niet geleid tot een toename van de spaarquote.$$, 'inline'),
  ('132bfcff-e735-43ad-9488-a9a9a3b924b2', 'c1892a3e-eb61-4ff8-bc5b-58420322f41e', $$hogere refirente leidt door marktmacht van banken niet tot hogere spaarrente$$,
   $$economie-vwo-2026-ii-flexibele-inflatie-context2.png$$,
   $$Het verhogen van de refirente zou moeten leiden tot een hogere spaarrente. Door marktmacht van banken gebeurt dit niet.$$, 'inline'),
  ('8aeee1f3-6d5f-4399-9156-62684cea3451', 'c1892a3e-eb61-4ff8-bc5b-58420322f41e', $$overheid wil inflatie verlagen door flexwerk te stimuleren$$,
   $$economie-vwo-2026-ii-flexibele-inflatie-context3.png$$,
   $$De overheid van het land wil de inflatie verlagen door flexwerk (werk op basis van flexibele arbeidscontracten) te stimuleren.$$, 'inline'),
  ('e2dc0808-e6c4-4759-bde4-7a00cba421f2', 'c1892a3e-eb61-4ff8-bc5b-58420322f41e', $$laagconjunctuur: IS₀ verschuift naar IS₁; centrale bank met één rentestap terug naar evenwicht$$,
   $$economie-vwo-2026-ii-flexibele-inflatie-context4.png$$,
   $$Figuur 2 toont het IS-MB-GA model met een flexibele arbeidsmarkt. In dit land ontstaat er een laagconjunctuur waardoor IS₀ verschuift naar IS₁. Neem aan dat de centrale bank de economie met één rentestap terugbrengt naar het evenwicht.$$, 'inline'),
  ('ac63af81-3b34-4a94-8551-571b617dc8c9', 'c1892a3e-eb61-4ff8-bc5b-58420322f41e', $$figuur 2: IS-MB-GA model met flexibele arbeidsmarkt, met legenda$$,
   $$economie-vwo-2026-ii-flexibele-inflatie-context5.png$$,
   $$Figuur 2 IS-MB-GA model
Bovenste grafiek: verticale as reële rente (6 tot 12), horizontale as inkomen (0 tot 600). IS₀ dalend van 12 bij 0 naar 6 bij 600; IS₁ dalend van 11 bij 0 naar 6 bij 500; horizontale lijn MB₀ bij 8. IS₀ snijdt MB₀ bij 400 (Y*), IS₁ snijdt MB₀ bij 300.
Onderste grafiek: verticale as inflatie (0 tot 9), horizontale as inkomen (0 tot 600). Stijgende lijn GA₀ (van ongeveer 1 bij 180 tot 9 bij ongeveer 560).
Legenda:
MB₀ = MB-curve in uitgangssituatie (bij Y = Y*)
IS₀ = IS-curve in uitgangssituatie
IS₁ = IS-curve tijdens laagconjunctuur
GA₀ = geaggregeerd aanbod
Y = inkomen$$, 'inline'),
  ('7460af17-c6cc-4944-bac7-c3331dda5037', 'c1892a3e-eb61-4ff8-bc5b-58420322f41e', $$uitwerkbijlage vraag 16: figuur 2 en tabel$$,
   $$economie-vwo-2026-ii-flexibele-inflatie-context6.png$$,
   $$uitwerkbijlage vraag 16
Figuur 2 IS-MB-GA model (kopie van figuur 2)
Tabel
| reële rente | inkomen | inflatie
uitgangssituatie | 8 | 400 |
nieuwe situatie | | |$$, 'uitwerkbijlage'),
  ('c35f0b10-d2a9-4239-b88c-4b872f884272', 'a57d5f7c-fb0a-4465-9ff2-ac3864a49be9', $$inleiding: 1.227 notarissen; klanten letten op prijs, reiskosten en persoonlijk contact$$,
   $$economie-vwo-2026-ii-waarvan-akte-context1.png$$,
   $$Een notaris heeft als taak om officiële documenten op te stellen zoals een hypotheekakte. Hierin staan alle voorwaarden waaraan zowel de bank als het huishouden dat een hypotheek wil afsluiten moeten voldoen. Er zijn op de markt 1.227 notarissen actief. Bij het zoeken naar een notaris kijken mensen niet alleen naar de prijs, maar ook naar reiskosten en persoonlijk contact.$$, 'inline'),
  ('404588da-7674-467d-9f1f-b0fd4d5b15dc', 'a57d5f7c-fb0a-4465-9ff2-ac3864a49be9', $$notariskantoor Athena investeert in AI en vraagt patent aan$$,
   $$economie-vwo-2026-ii-waarvan-akte-context2.png$$,
   $$Notariskantoor Athena investeert in een eigen AI-omgeving (= een digitaal systeem met kunstmatige intelligentie) die hypotheekakten kan opstellen. De bank en het huishouden geven elk hun voorwaarden aan. AI stelt daarna de hypotheekakte op. Athena vraagt een patent aan op bovenstaande ontwikkeling.$$, 'inline'),
  ('b0445f39-52bb-49d9-ad40-e5628cf20bcc', 'a57d5f7c-fb0a-4465-9ff2-ac3864a49be9', $$uitgangssituatie: 2 miljoen akten, marktaandeel Athena 3%, uurloon € 200, winst € 100 per akte$$,
   $$economie-vwo-2026-ii-waarvan-akte-context3.png$$,
   $$Notarissen stellen jaarlijks twee miljoen hypotheekakten op. In de uitgangssituatie verkoopt Athena 3% van de totale hoeveelheid hypotheekakten. Het opstellen van een hypotheekakte kost drie uur zonder AI. Het uurloon van notarissen is € 200. Athena hanteert een gemiddelde winst van € 100 bovenop de kosten.$$, 'inline'),
  ('5fa3a155-9a55-46d1-b6c4-172dd290fba2', 'a57d5f7c-fb0a-4465-9ff2-ac3864a49be9', $$door AI variabele kosten € 50 per akte; marktaandeel Athena 20%$$,
   $$economie-vwo-2026-ii-waarvan-akte-context4.png$$,
   $$Door AI zijn er geen loonkosten meer en worden de variabele kosten per akte € 50 waardoor de prijs van Athena daalt. Athena blijft een gemiddelde winst van € 100 hanteren. Athena sluit 20% van de totale hoeveelheid hypotheekakten af. Constante kosten blijven buiten beschouwing.$$, 'inline'),
  ('747935c5-ebb8-4578-b8aa-1f4ad0588e8a', 'a57d5f7c-fb0a-4465-9ff2-ac3864a49be9', $$inzet van AI leidt tot positieve externe effecten$$,
   $$economie-vwo-2026-ii-waarvan-akte-context5.png$$,
   $$Door de inzet van AI treden er positieve externe effecten op.$$, 'inline'),
  ('024e96c2-44b7-4b2e-a9c5-de98afda88ac', '179c8422-6ce0-451d-91d0-09855fa49951', $$inleiding: Kroatië treedt per 2023 toe tot de EMU; geen onafhankelijk monetair beleid meer$$,
   $$economie-vwo-2026-ii-welkom-kroatie-context1.png$$,
   $$Per 1 januari 2023 is Kroatië als twintigste land toegetreden tot de Economische en Monetaire Unie (EMU). Hiermee hebben zij de euro als wettig betaalmiddel ingevoerd. Als gevolg van de toetreding kan de Centrale Bank van Kroatië (KCB) geen onafhankelijk monetair beleid meer voeren.$$, 'inline'),
  ('790450a3-05a9-4035-a9de-047981c5e315', '179c8422-6ce0-451d-91d0-09855fa49951', $$stelling econoom: rentebeleid ECB kan procyclisch werken voor Kroatië$$,
   $$economie-vwo-2026-ii-welkom-kroatie-context2.png$$,
   $$Een econoom stelt: “als Kroatië als enige lidstaat van de EMU zich in een laagconjunctuur bevindt, dan kan het rentebeleid van de ECB een procyclisch effect hebben op de conjunctuur van Kroatië.”$$, 'inline'),
  ('cc250c20-9c9a-4621-b87b-7d9e1ace3465', '179c8422-6ce0-451d-91d0-09855fa49951', $$econoom analyseert geldstromen op de lopende rekening voor en na toetreding$$,
   $$economie-vwo-2026-ii-welkom-kroatie-context3.png$$,
   $$De econoom analyseert geldstromen op de lopende rekening zowel voor de toetreding (2022) als na de toetreding (2023).$$, 'inline'),
  ('567a15cb-8661-4bdd-a573-5bca691f0de0', '179c8422-6ce0-451d-91d0-09855fa49951', $$figuur 3: geldstromen lopende rekening met de EU$$,
   $$economie-vwo-2026-ii-welkom-kroatie-context4.png$$,
   $$Figuur 3 Geldstromen lopende rekening met de EU
voor de toetreding: EU (2022) → Kroatië (2022): 0,2Yₖ; Kroatië (2022) → EU (2022): 0,2Yₖ
na de toetreding: EU (2023) → Kroatië (2023): 0,22Yₖ; Kroatië (2023) → EU (2023): 0,205Yₖ
Yₖ = Nationaal inkomen van Kroatië in het betreffende jaar in euro’s.$$, 'inline'),
  ('85c71329-070c-4055-89dc-b9c5e80bc1d2', '179c8422-6ce0-451d-91d0-09855fa49951', $$handel van Kroatië met rest van de wereld is in evenwicht$$,
   $$economie-vwo-2026-ii-welkom-kroatie-context5.png$$,
   $$Neem aan dat de handel van Kroatië met de rest van de wereld in evenwicht is.$$, 'inline'),
  ('6d33a53a-a78b-4a32-9eb5-7492d8b37e46', '179c8422-6ce0-451d-91d0-09855fa49951', $$nationaal inkomen 2023 stijgt met 3,4% tot € 68,9 miljard$$,
   $$economie-vwo-2026-ii-welkom-kroatie-context6.png$$,
   $$In 2023 stijgt het nationaal inkomen van Kroatië ten opzichte van 2022 met 3,4% tot € 68,9 miljard.$$, 'inline'),
  ('e22199e7-5779-4974-b1b9-1b0449bf6259', '179c8422-6ce0-451d-91d0-09855fa49951', $$invoering mededingingswet en mededingingsautoriteit$$,
   $$economie-vwo-2026-ii-welkom-kroatie-context7.png$$,
   $$De toetreding tot de EMU heeft voor Kroatië nog meer effecten gehad zoals de invoering van de mededingingswet. Deze wet bevat regels ten aanzien van kartels en misbruik van een economische machtspositie. De mededingingsautoriteit handhaaft de mededingingswet.$$, 'inline'),
  ('3ef4be9c-233d-4628-9edb-892930689266', '429f2322-47b7-44d7-8f1a-e92a8d1ed8da', $$inleiding: klimaatakkoord van Parijs onder leiding van de VN; belasten van CO₂-uitstoot$$,
   $$economie-vwo-2026-ii-klimaatbeleid-context1.png$$,
   $$Om de mondiale CO₂-uitstoot terug te brengen, is onder leiding van de Verenigde Naties (VN) het klimaatakkoord van Parijs opgesteld. Een onderdeel van dit akkoord betreft afspraken over het voeren van klimaatbeleid, zoals het belasten van CO₂-uitstoot.$$, 'inline'),
  ('0ac661d6-f0c6-4aa5-98f4-baf0693e4993', '429f2322-47b7-44d7-8f1a-e92a8d1ed8da', $$econoom onderzoekt netto baten van klimaatbeleid voor 195 landen$$,
   $$economie-vwo-2026-ii-klimaatbeleid-context2.png$$,
   $$Een econoom heeft de netto baten van klimaatbeleid onderzocht voor 195 landen (zie figuur 4). In dit model wordt aangenomen dat alle landen even groot zijn en dus zijn de netto baten per land gelijk.$$, 'inline'),
  ('7e9d957b-dab0-4462-a0cf-30c97030f76f', '429f2322-47b7-44d7-8f1a-e92a8d1ed8da', $$figuur 4: netto baten per land$$,
   $$economie-vwo-2026-ii-klimaatbeleid-context3.png$$,
   $$Figuur 4 Netto baten per land
verticale as: netto baten in miljarden € (0 tot 400); horizontale as: aantal landen met klimaatbeleid (0 tot 200).
netto baten met klimaatbeleid: stijgende lijn van 0 bij ongeveer 17 landen tot ongeveer 350 bij 195 landen.
netto baten zonder klimaatbeleid: stijgende lijn van ongeveer 25 bij 0 landen tot ongeveer 120 bij 195 landen.
De lijnen snijden elkaar bij 40 landen (ongeveer € 45 miljard).$$, 'inline'),
  ('f73a5e44-74ac-481e-a8d7-fc26403307e0', '429f2322-47b7-44d7-8f1a-e92a8d1ed8da', $$toelichting figuur 4: netto baten hangen af van het aantal landen met klimaatbeleid$$,
   $$economie-vwo-2026-ii-klimaatbeleid-context4.png$$,
   $$Figuur 4 toont aan dat de netto baten van een land afhankelijk zijn van hoeveel landen in totaal klimaatbeleid voeren. Als bijvoorbeeld 80 landen klimaatbeleid voeren, kan een enkel ander land kiezen tussen klimaatbeleid voeren (de netto baten van dit land zijn dan ongeveer € 120 miljard) of geen klimaatbeleid voeren (de netto baten van dit land zijn dan ongeveer € 60 miljard).$$, 'inline'),
  ('99f5c596-36fd-4734-a269-10ee05d2d85e', '429f2322-47b7-44d7-8f1a-e92a8d1ed8da', $$overheden met overheidssaldo 0 willen huidige generatie werkenden ontzien$$,
   $$economie-vwo-2026-ii-klimaatbeleid-context5.png$$,
   $$De meeste overheden hebben momenteel een overheidssaldo van 0. Overheden willen niet dat het voeren van klimaatbeleid ten koste gaat van de bestedingen van de huidige generatie werkenden.$$, 'inline'),
  ('d673c74b-5394-4b4c-af9f-79e0394b7d95', '429f2322-47b7-44d7-8f1a-e92a8d1ed8da', $$voorwaarden a, b en c voor het klimaatakkoord$$,
   $$economie-vwo-2026-ii-klimaatbeleid-context6.png$$,
   $$Bij een volgende vergadering van landen die deelnemen aan het klimaatakkoord, worden onderstaande voorwaarden besproken: a Alle deelnemers aan het akkoord worden verplicht klimaatbeleid te voeren. b Terugtrekking uit het akkoord is niet mogelijk. c Landen zijn zelf verantwoordelijk voor het klimaatbeleid en het meten van de resultaten hiervan.$$, 'inline'),
  ('1b465909-ab5e-4e38-986e-588eaa49d5fe', '429f2322-47b7-44d7-8f1a-e92a8d1ed8da', $$risico op principaal-agentprobleem met de VN als principaal$$,
   $$economie-vwo-2026-ii-klimaatbeleid-context7.png$$,
   $$Op basis van bovenstaande voorwaarden voorziet de econoom dat er een risico ontstaat op een principaal-agent probleem, waarbij de VN optreedt als principaal.$$, 'inline');

